// OpenCode V2 目录型插件入口。
//
// V2 在加载“目录型插件”时会忽略 package.json 的 main/exports，直接查找
// 插件根目录下的 index.ts / index.js。V1 才按 package.json 的 main 解析。
// 因此这里提供一个根入口，复用 src/index.ts 的真实实现。
export { default, AutoModelConfigPlugin } from "./src/index"

import { AutoModelConfigPlugin } from "./plugin"

export { AutoModelConfigPlugin }
export default AutoModelConfigPlugin

import { isDeepStrictEqual } from "node:util"
import { watchFile, unwatchFile } from "node:fs"
import path from "node:path"
import { Plugin, Model } from "@opencode/plugin"
import { ModelsDevCache } from "../cache/models-dev-cache"
import { loadConfig, getMappedProviders } from "../mapping/parser"
import { resolveProviderModels } from "../mapping/resolver"
import { fieldsFromModelsDev } from "../utils/fields-mapper"
import { ConfigDumper, type EnhancedModelResult } from "../debug/config-dumper"
import { applyCostMapping } from "../cost/apply-cost-mapping"
import { getGlobalConfigDir } from "../utils/paths"
import type { AutoModelConfig, ModelsDevData, ResolvedModel } from "../types"

type PlainRecord = Record<string, unknown>

interface Snapshot {
  pluginConfig: AutoModelConfig
  modelsDev: ModelsDevData
  allResolved: Map<string, Map<string, ResolvedModel>>
  cacheAge: number
  dumper: ConfigDumper | null
}

async function loadSnapshot(projectDir: string): Promise<Snapshot | null> {
  const pluginConfig = await loadConfig({ projectDirectory: projectDir })
  if (!pluginConfig) return null
  const cache = new ModelsDevCache({
    cachePath: pluginConfig.cachePath,
    cacheTTL: pluginConfig.cacheTTL,
    projectDirectory: projectDir,
  })
  const modelsDev = await cache.get()
  if (!modelsDev) throw new Error("No models.dev data available")
  const cacheAge = await cache.getAge()
  const allResolved = new Map<string, Map<string, ResolvedModel>>()
  for (const provider of getMappedProviders(pluginConfig)) {
    allResolved.set(provider, resolveProviderModels(modelsDev, pluginConfig, provider))
  }
  const dumper = pluginConfig.debug?.enabled
    ? new ConfigDumper({ ...pluginConfig.debug, projectDirectory: projectDir })
    : null
  return { pluginConfig, modelsDev, allResolved, cacheAge, dumper }
}

/** `Model.Info.default(providerID, modelID)` 的真实参数类型（带 brand 的 Provider.ID / Model.ID）。 */
type ModelDefaultArgs = Parameters<typeof Model.Info.default>

function isPlainObject(value: unknown): value is PlainRecord {
  return typeof value === "object" && value !== null && !Array.isArray(value)
}

/**
 * 判断字段当前值是否仍等于 OpenCode V2 模型的初始默认值。
 *
 * 默认值完全来自实际的 `Model.Info.default(providerID, modelID)`（其内部包含实际的
 * `Model.Capabilities.default()`），不再硬编码 name/limit/cost 等常量，从而自动跟随
 * OpenCode 自身默认值的变化。
 *
 * 合并语义：
 * - 对象型默认字段（如 `limit` / `capabilities`）按**叶子**递归比较：只填充仍等于默认值
 *   或 `undefined` 的叶子，绝不覆盖用户显式设置的叶子。这样当宿主把用户的部分覆盖
 *   （例如只写了 `limit.output`）合并到默认对象上时，同一对象的其它默认叶子仍会被补齐。
 * - 数组型字段（如 `cost`）保持**整对象**语义：仅当当前数组仍等于默认值时才整体替换，
 *   避免破坏用户自建的数组（例如自定义阶梯定价）。
 * - 标量字段（如 `name` / `family`）仍按整值深度比较。
 *
 * 宿主契约假设（当前无法端到端验证）：宿主对用户未显式配置的字段暴露的值应等于
 * `Model.Info.default()` 的返回值。若宿主持有其它基底并据此预填字段，可能出现字段
 * 静默不填充；需通过 debug dump 观察实际值来确认。相关测试均为 mock ModelEditor 的
 * adapter 测试，不代表已端到端验证。
 *
 * 注意：若用户显式把某字段设置成与默认值完全相同的值（例如把 name 写成与 modelID 相同，
 * 或把 limit 写成默认的 200000/32000），则该值与初始默认值不可区分，会被视为可自动填充。
 * 这是可接受的折衷。
 */
function mergeModelField(
  defaults: PlainRecord,
  key: string,
  currentValue: unknown,
  desiredValue: unknown,
): { shouldFill: boolean; value: unknown } {
  // 未设置 → 直接填充
  if (currentValue === undefined) {
    return { shouldFill: true, value: desiredValue }
  }

  const defaultValue = key in defaults ? defaults[key] : undefined

  // 数组型字段：整对象语义，只有当前值仍等于默认值时才整体替换
  if (Array.isArray(desiredValue)) {
    if (defaultValue === undefined) {
      // 默认值中没有该字段，但用户已设置 → 用户显式值，保留
      return { shouldFill: false, value: currentValue }
    }
    return isDeepStrictEqual(currentValue, defaultValue)
      ? { shouldFill: true, value: desiredValue }
      : { shouldFill: false, value: currentValue }
  }

  // 对象型字段：按叶子递归合并
  if (isPlainObject(desiredValue)) {
    if (!isPlainObject(currentValue)) {
      // 当前值不是对象，视为用户显式设置，保持
      return { shouldFill: false, value: currentValue }
    }

    const defaultObject = isPlainObject(defaultValue) ? defaultValue : {}
    const merged: PlainRecord = { ...currentValue }
    let changed = false

    for (const [leafKey, leafDesired] of Object.entries(desiredValue)) {
      const leafDefault = leafKey in defaultObject ? defaultObject[leafKey] : undefined
      const leafCurrent = currentValue[leafKey]

      // 嵌套对象递归处理，保留用户在这一层的显式叶子
      if (isPlainObject(leafDesired)) {
        const nested = mergeModelField(defaultObject, leafKey, leafCurrent, leafDesired)
        if (nested.shouldFill) {
          merged[leafKey] = nested.value
          changed = true
        }
        continue
      }

      // 当前叶子未设置 → 填充
      if (leafCurrent === undefined) {
        merged[leafKey] = leafDesired
        changed = true
        continue
      }

      // 默认值中没有该叶子，但用户已设置 → 用户显式值，保留
      if (leafDefault === undefined) {
        continue
      }

      // 当前叶子仍等于默认值 → 填充；否则视为用户显式覆盖
      if (isDeepStrictEqual(leafCurrent, leafDefault)) {
        merged[leafKey] = leafDesired
        changed = true
      }
    }

    return changed
      ? { shouldFill: true, value: merged }
      : { shouldFill: false, value: currentValue }
  }

  // 标量字段
  if (defaultValue === undefined) {
    return { shouldFill: false, value: currentValue }
  }
  return isDeepStrictEqual(currentValue, defaultValue)
    ? { shouldFill: true, value: desiredValue }
    : { shouldFill: false, value: currentValue }
}

export const AutoModelConfigPlugin = Plugin.define({
  id: "opencode-auto-model-config",
  async setup(ctx) {
    const projectDir = ctx.location?.directory ?? process.cwd()
    let snapshot: Snapshot | null = null
    let disposed = false
    let revision = 0
    let handledRevision = -1
    let running = false
    let ready = false
    let timer: ReturnType<typeof setTimeout> | undefined

    const report = (error: unknown) => {
      console.error("[auto-model-config] 刷新模型数据失败:", error)
    }
    const refresh = async (initial = false) => {
      if (disposed || running || (!initial && handledRevision === revision)) return
      running = true
      try {
        let current: number
        do {
          current = revision
          try {
            const next = await loadSnapshot(projectDir)
            // 串行读取；丢弃读取期间已被新事件取代的结果。
            if (disposed) return
            if (current !== revision) continue
            snapshot = next
            if (!initial) await ctx.model.reload()
          } catch (error) {
            // 保留最后成功快照，后续配置事件仍可重试。
            if (!disposed) report(error)
          }
          if (!disposed) handledRevision = current
        } while (!disposed && current !== revision)
      } finally {
        running = false
      }
    }
    const changed = () => {
      if (disposed) return
      revision++
      if (timer) clearTimeout(timer)
      timer = setTimeout(() => {
        timer = undefined
        if (ready) void refresh()
      }, 75)
    }
    // 按文件轮询也能发现尚不存在的全局目录，无需创建宿主目录。
    const files = [...new Set([projectDir, getGlobalConfigDir()])].flatMap((directory) =>
      ["jsonc", "json"].map((extension) => path.join(directory, `oc-auto-model-config.${extension}`)),
    )
    for (const file of files) watchFile(file, { interval: 250, persistent: false }, changed)
    const cleanup = () => {
      if (disposed) return
      disposed = true
      if (timer) clearTimeout(timer)
      for (const file of files) unwatchFile(file, changed)
    }

    // 只注册一次：宿主 reload 重建干净模型基底并按序重放 transform，不重新执行 setup。
    // transform 由宿主 Scope 自动释放；cleanup 只清理插件自有的监听和计时器。
    //
    // 必须先于 refresh 注册：宿主按注册顺序重放 transform，排在本插件之后的插件
    // （如 opencode-dcp）会在自己的 transform 里缓存 model.limit.context；若本插件
    // 注册更晚，它们每轮重放都先读后填，永远拿到 Model.Info.default 的默认 limit
    // （context=200000/output=32000），reload 也无法纠正（重放顺序不随 reload 改变）。
    // snapshot 未就绪时 callback 直接跳过（见下方 !snapshot 防护）。
    await Promise.resolve(ctx.model.transform((editor) => {
      if (disposed || !snapshot) return
      const { pluginConfig, modelsDev, allResolved, cacheAge, dumper } = snapshot
      const enhancedModels: Record<string, Record<string, EnhancedModelResult>> = {}

      for (const [providerName, resolvedMap] of allResolved) {
        // 检查 provider 是否存在于 editor 中
        const existingProvider = editor.provider.get(providerName)
        if (!existingProvider) {
          continue
        }

        enhancedModels[providerName] = {}

        for (const [modelId, resolved] of resolvedMap) {
          if (resolved.warning) {
            enhancedModels[providerName][modelId] = {
              source: resolved.source,
              filledFields: [],
              warning: resolved.warning,
            }
            continue
          }

          // 检查 model 是否存在于 provider 中
          const existingModel = editor.get(providerName, modelId)
          if (!existingModel) {
            enhancedModels[providerName][modelId] = {
              source: resolved.source,
              resolvedSource: resolved.resolvedSource,
              filledFields: [],
              skipped: true,
            }
            continue
          }

          const v2Fields = fieldsFromModelsDev(resolved.modelData)
          const actuallyFilledFields: string[] = []

          // 每个模型的初始默认值直接来自 OpenCode V2 契约，避免硬编码默认常量。
          // 宿主假设：未显式配置字段的当前值等于此处返回的默认值（见 mergeModelField 注释）。
          const modelDefaults = Model.Info.default(
            providerName as ModelDefaultArgs[0],
            modelId as ModelDefaultArgs[1],
          ) as unknown as PlainRecord

          // 仅补全未设置或仍为 Model.Info.default 默认初值的叶子，绝不覆盖用户显式值
          // 特例：当配置了 override.cost === true 且 models.dev 存在 cost 数据时，强制覆盖 cost 字段
          const forceOverrideCost = pluginConfig.override?.cost === true && v2Fields.cost !== undefined

          editor.update(providerName, modelId, (modelToUpdate) => {
            const mutableModel = modelToUpdate as unknown as PlainRecord
            for (const [key, value] of Object.entries(v2Fields)) {
              if (value === undefined) continue

              if (key === "cost" && forceOverrideCost) {
                mutableModel[key] = value
                actuallyFilledFields.push(key)
                continue
              }

              const { shouldFill, value: mergedValue } = mergeModelField(
                modelDefaults,
                key,
                mutableModel[key],
                value,
              )

              if (shouldFill) {
                mutableModel[key] = mergedValue
                actuallyFilledFields.push(key)
              }
            }
          })

          enhancedModels[providerName][modelId] = {
            source: resolved.source,
            resolvedSource: resolved.resolvedSource,
            filledFields: actuallyFilledFields,
            model: editor.get(providerName, modelId) as unknown as Record<string, unknown>,
          }
        }
      }

      // 独立于 mapping：只处理 costMapping 里列出的模型，且只写 cost。
      // 放在 mapping 之后，重叠时价格以 costMapping 为准。不读取 override.cost，也不扫描 editor.list()。
      if (pluginConfig.costMapping && Object.keys(pluginConfig.costMapping).length > 0) {
        applyCostMapping(editor, modelsDev, pluginConfig.costMapping, enhancedModels)
      }

      if (dumper) {
        dumper.dumpV2(enhancedModels, allResolved, cacheAge).catch((err) => {
          console.error("[auto-model-config] Failed to write debug dump:", err)
        })
      }
    })).catch((error) => {
      cleanup()
      throw error
    })

    await refresh(true)
    ready = true

    // 初始填充只落在本轮 transform 产物上；对排在本插件之后的 transform（如
    // opencode-dcp 的 limit 缓存）而言，填充前的默认值可能在早先一轮已被读过。
    // 显式 reload 一轮，让已填充的基底按注册顺序完整重放，后续插件才能拿到真实
    // limit 而非 Model.Info.default 的默认值。
    if (snapshot && !disposed) {
      try {
        await ctx.model.reload()
      } catch (error) {
        report(error)
      }
    }

    return cleanup
  },
})

export default AutoModelConfigPlugin

// opencode-auto-model-config 插件的共享类型

/**
 * models.dev API 顶层响应（按 provider ID 索引）
 */
export interface ModelsDevData {
  [providerId: string]: ModelsDevProvider
}

/**
 * models.dev 中的 provider 条目
 */
export interface ModelsDevProvider {
  id: string
  name: string
  npm: string
  env: string[]
  api?: string
  doc?: string
  models: Record<string, ModelsDevModel>
}

/**
 * models.dev 中的单个模型条目
 */
export interface ModelsDevModel {
  id: string
  canonical_model_id?: string
  name: string
  family?: string
  attachment: boolean
  reasoning: boolean
  tool_call: boolean
  structured_output?: boolean
  temperature?: boolean
  knowledge?: string
  release_date: string
  last_updated: string
  modalities: {
    input: string[]
    output: string[]
  }
  open_weights: boolean
  cost?: ModelsDevCost
  limit: {
    context: number
    input?: number
    output: number
  }
  interleaved?: boolean | { field: string }
  status?: string
  provider?: string
  experimental?: boolean
}

export interface ModelsDevCost {
  input: number
  output: number
  cache_read?: number
  cache_write?: number
  reasoning?: number
  context_over_200k?: {
    input: number
    output: number
    cache_read?: number
  }
}

/** models.dev 模型条目的字符串条件；provider 限定 provider id */
export type ModelMatchCriteria = Record<string, string>

/**
 * 插件配置（来自 oc-auto-model-config.jsonc 或 oc-auto-model-config.json）
 */
export interface AutoModelConfig {
  /** 缓存 TTL，单位为秒（默认：86400 = 24 小时） */
  cacheTTL?: number
  /** 自定义缓存路径；null/未设置时使用 XDG 配置目录下的 models-dev.json */
  cachePath?: string | null
  /** 映射关系：provider -> { modelId -> "modelsdev-provider/modelsdev-modelId" } */
  mapping: Record<string, Record<string, string | ModelMatchCriteria>>
  /**
   * 仅价格映射，结构与 mapping 相同。
   * 只覆盖列出的模型的 cost，不依赖 override.cost，也不扫描未列出的模型。
   */
  costMapping?: Record<string, Record<string, string | ModelMatchCriteria>>
  /** 调试模式配置 */
  debug?: DebugConfig
  /** 覆盖行为配置 */
  override?: OverrideConfig
}

/**
 * 字段强制覆盖配置
 */
export interface OverrideConfig {
  /** 是否强行覆盖模型价格（即使用户或宿主已显式设置 cost） */
  cost?: boolean
}

/**
 * 调试模式配置
 */
export interface DebugConfig {
  /** 启用调试输出 */
  enabled: boolean
  /** 输出文件路径（默认：XDG 配置目录下的 expanded-config.json） */
  dumpPath?: string
  /** 仅输出变更的字段（默认：true） */
  diffOnly?: boolean
}

/**
 * 单个模型映射的解析结果
 */
export interface ResolvedModel {
  /** models.dev 中的数据源（如 "opencode-go/gpt-5.4"） */
  source: string
  /** canonical 回退实际命中的 provider/model key；精确查找时不设置 */
  resolvedSource?: string
  /** 完整的 models.dev 模型数据 */
  modelData: ModelsDevModel
  /** 需要填充到 OpenCode V2 模型元数据中的字段 */
  filledFields: string[]
  /** 警告信息（如有） */
  warning?: string
}

# @misakacloud/opencode-auto-model-config

独立的 OpenCode 插件，单独安装、配置和发布。[仓库总览](../../README.md) · [@misakacloud/opencode-auto-retry](../auto-retry/README.md) · [@misakacloud/opencode-skill-filter](../skill-filter/README.md)

OpenCode 插件：根据 [models.dev](https://models.dev) 数据为自定义 provider 自动填充模型元数据。

## 介绍

当你在 OpenCode 中配置自定义 provider（如 OpenAI 兼容 API、第三方模型服务）时，需要手动填写模型的详细信息（上下文窗口、能力、费用等）。这个插件可以自动从 models.dev 获取这些元数据，并填充到你的 OpenCode 配置中。

主要功能：

- 自动从 models.dev 获取模型元数据
- 支持自定义 provider 和模型 ID 映射
- 配置保存后自动刷新模型列表，无需重启 OpenCode
- 本地缓存（24 小时），避免频繁请求
- 不覆盖用户已填写的字段
- 支持调试模式，可查看配置变更

## 使用

### 在 OpenCode 中启用

> 仅支持 OpenCode V2（`@opencode/plugin` 2.x）。
> 强烈建议通过版本号锁定，否则 OpenCode 是否会更新插件是薛定谔的。

在 `opencode.json` 中配置原生 `plugins` 和 `providers`：

```json
{
	"plugins": ["@misakacloud/opencode-auto-model-config@latest"],
	"providers": {
		"my-openai": {
			"models": {
				"gpt-4o": {}
			}
		}
	}
}
```

### 本地路径安装

OpenCode V2 加载目录型插件时解析包目录根部的 `index.ts`（转发到 `src/index.ts`），不读取 `package.json` 的 `main` 作为目录入口。将示例绝对路径换成本机实际路径，任选一种形式，不要与发布包重复安装：

```jsonc
{
  "plugins": ["/data/SourceCode/opencode-plugins/packages/auto-model-config"]
}
```

也可写 `{ package, options }`；本插件**不支持内联 options（不读取 `ctx.options`），仅从配置文件读取**，因此 `options` 只能为空，映射须写在 `oc-auto-model-config.jsonc` 或 `.json`：

```jsonc
{
  "plugins": [
    {
      "package": "/data/SourceCode/opencode-plugins/packages/auto-model-config",
      "options": {}
    }
  ]
}
```

### 插件顺序约束：依赖模型元数据的插件必须排在本插件之后

> **TL;DR：任何会读取模型元数据（`limit` / `cost` / `capabilities` 等）的插件，在 `plugins` 数组里必须排在本插件之后。**

宿主按 `plugins` 数组顺序串行执行各插件的 `setup`，并按 **transform 注册顺序**重放模型变换。本插件通过 `ctx.model.transform` 向模型填充元数据，因此：

- 排在本插件**之后**的插件：每轮重放时先看到本插件填充好的值，读到真实的 `limit` 等元数据。
- 排在本插件**之前**的插件：每轮重放都先于本插件执行，只能读到 `Model.Info.default` 的默认值（例如 `limit.context = 200000` / `limit.output = 32000`）。本插件随后填充的真实值对它们不可见，而且 **`ctx.model.reload()` 也无法纠正**——reload 重建的是干净基底并按同一顺序重放，先读后填的相对顺序不会改变。

典型受害者是像 [opencode-dcp](https://github.com/tarquinen/opencode-dcp) 这类在初始化时缓存 `model.limit.context` 的插件：它若排在本插件之前，会一直拿着默认的 200000 作为模型上下文窗口，导致上下文用量百分比与阈值判断严重失真。

正确示例：

```json
{
	"plugins": [
		"@misakacloud/opencode-auto-model-config@latest",
		"@tarquinen/opencode-dcp@3.2.1"
	]
}
```

本插件自身也会在初始填充完成后主动触发一次 `ctx.model.reload()`，让填充后的基底立即完整重放一轮，尽力缩短后续插件读到默认值的时间窗；但这只是对非常规加载时序的加固，**不能替代数组顺序约束**。

## 配置

插件支持 `oc-auto-model-config.jsonc` 与 `oc-auto-model-config.json`。同一目录里只要有 `.jsonc` 就用它，不再读同目录的 `.json`。查找顺序：

1. 当前项目根目录的 `oc-auto-model-config.jsonc`
2. 当前项目根目录的 `oc-auto-model-config.json`
3. 全局目录的 `oc-auto-model-config.jsonc`
4. 全局目录的 `oc-auto-model-config.json`

全局目录是 `XDG_CONFIG_HOME/opencode`，未设置时为 `~/.config/opencode/`。`.jsonc` 可以写 `//`、`/* */` 注释和尾逗号，也接受文件开头的 UTF-8 BOM。字符串里的 `//`、`/*`、`,`、`}` 按原样保留。文件语法错误时会警告，并跳过同目录的另一种扩展名，再继续下一目录。内容能解析、但没有可用的 `mapping` / `costMapping` 时，仍不启用，也不会改去读别的文件。

插件会监听上述项目与全局配置文件的创建、修改和删除，重新按相同优先级读取配置，再通过 V2 `ctx.model.reload()` 刷新模型列表。启动时没有配置也可稍后创建；移除映射后，下次刷新不再应用该映射。模型数据仍遵循 `cacheTTL` 缓存策略，不会因每次保存都强制下载 models.dev。

### 配置文件格式

```json
{
	"mapping": {
		"your-provider-name": {
			"model-id": "modelsdev-provider/modelsdev-model-id"
		}
	}
}
```

目标既能写 `provider/model`（如 `openai/gpt-4o`），也能写 models.dev 的 `canonical_model_id`（如 `tencent/hy4-flash`）。后者用于官方 provider 未出现在 models.dev provider 表里的情况：插件会遍历所有 provider，找 `canonical_model_id` 相同的条目作为数据来源。多个候选时依次按「模型 key 等于 canonical 最后一段」→「provider id 等于 canonical 第一段」→ provider id 字母序选取，结果确定。命中 canonical 时，debug dump 的 `_source` 仍显示你配置的 canonical id，`_resolvedSource` 显示实际命中的 `provider/model`。

右侧也可以写成对象，进入**精确条件模式**：对象的每个字段都是匹配条件（AND），按 models.dev 条目的同名字段做大小写不敏感的字符串比较；`provider` 是特殊字段，用来限定 provider id。条件字段在 models.dev 条目中必须存在且为字符串才会命中（如 `limit`、`cost`、`modalities` 这类非字符串字段不能作为条件）。

```jsonc
{
	"mapping": {
		"your-provider-name": {
			"hy4-flash": {
				"name": "Hy4 flash",
				"canonical_model_id": "tencent/hy4-flash"
			}
		}
	}
}
```

对象模式的候选排序、无匹配 warning、`_resolvedSource` 行为与字符串模式一致；debug dump 的 `_source` 会显示整个条件对象的 JSON。`costMapping` 也支持同样的两种写法。

### 示例

假设你的 OpenCode V2 配置中有：

```json
{
	"providers": {
		"my-openai": {
			"models": {
				"gpt-4o": {}
			}
		}
	}
}
```

在 `oc-auto-model-config.jsonc`（或 `.json`）中添加映射：

```json
{
	"mapping": {
		"my-openai": {
			"gpt-4o": "openai/gpt-4o"
		}
	}
}
```

启动 OpenCode 后，`gpt-4o` 模型会自动通过 V2 `ctx.model.transform` 填充以下原生字段：

> 此时数据来源 Provider 为 `openai`

- `name`: 模型显示名称
- `family`: 模型家族标识（若源数据包含）
- `capabilities`: 包含 `tools`（布尔）及输入输出模态 `input`/`output`
- `limit`: 上下文窗口 `context` 和输出限制 `output`（以及不同的 `input`）
- `cost`: 原生阶梯费用数组，包含基础费用与 `context_over_200k` 等 tier

同样的，如果你使用的 Provider 采用了 `provider/model` 命名格式，这里也是支持的：

```json
{
	"providers": {
		"my-openai": {
			"models": {
				"openai/gpt-4o": {}
			}
		}
	}
}
```

你可以在映射的时候使用：

```json
{
	"mapping": {
		"my-openai": {
			"openai/gpt-4o": "openai/gpt-4o"
		}
	}
}
```

那么此时还是用 OpenAI 的 `gpt-4o` 模型，数据来源为 `openai`。

### 配置选项

```json
{
	"mapping": {},
	"cacheTTL": 86400,
	"cachePath": "./models-dev.json",
	"debug": {
		"enabled": false,
		"dumpPath": "./expanded-config.json",
		"diffOnly": true
	},
	"override": {
		"cost": false
	}
}
```

**路径警示：**`cachePath` 与 `debug.dumpPath` 仅支持相对路径（OpenCode 在项目根运行时相对项目根）或绝对路径，不支持 `~`；代码把相对路径直接交给文件系统，实际基准是 OpenCode 进程工作目录，而非自动解析成项目根。这里使用 `./` 示范相对路径；若进程工作目录不确定，请改用绝对路径。省略时分别使用全局配置目录下的 `models-dev.json`、`expanded-config.json`。

- `mapping`: 完整元数据映射。与 `costMapping` 至少要有一组非空；只有空 `mapping`、或只写 `override.cost` 时插件不启用
- `costMapping`: 手填的仅价格映射，结构与 `mapping` 相同。只处理列出来的模型，且只覆盖 `cost`
- `cacheTTL`: 缓存有效期，单位秒（默认 86400 = 24 小时）
- `cachePath`: 自定义缓存文件路径
- `debug.enabled`: 启用调试输出。未匹配或源没有价格时，原因写在 dump 里，不会逐条刷屏
- `debug.dumpPath`: 调试输出文件路径
- `debug.diffOnly`: 仅输出变更的字段（默认 true）
- `override.cost`: 只作用于 `mapping`。为 true 时，即使用户显式配置了 `cost`，也会用该 mapping 源的价格覆盖。它不启用、也不阻止 `costMapping`

### 仅价格映射 `costMapping`

订阅或套餐 provider 的 models.dev 条目经常是 0 价，或者模型 ID 与按量 API 不一样。插件**不会**扫描全部模型，也**没有**内置 provider 名单或模型别名。需要估价时，自己写成 `costMapping`：

```json
{
	"costMapping": {
		"claude-code": {
			"claude-sonnet-4-6": "anthropic/claude-sonnet-4-6",
			"claude-sonnet-4-6[1m]": "anthropic/claude-sonnet-4-6"
		},
		"kimi-code-plan-cn": {
			"k3": "moonshotai-cn/kimi-k3"
		},
		"alibaba-coding-plan-cn": {
			"qwen3-max-2026-01-23": "alibaba-cn/qwen3-max"
		}
	}
}
```

上面的 ID 只是写法示例，必须和你当前 models.dev 里的真实条目一致。`[1m]` 这类后缀不会自动剥掉，套餐 ID 也不会自动改写成 API ID。

规则：

- 可以只写 `costMapping`，不必再写 `mapping`
- 只改 `cost`，`name` / `limit` / `capabilities` 等字段保持原样
- 与 `mapping` 指向同一模型时，先做完整元数据填充，再由 `costMapping` 覆盖价格
- `costMapping` 是显式覆盖，不看 `override.cost`
- 源 provider/模型不存在，或源条目没有数字 `cost` 时，保留原来的 `cost`，并在 debug dump 里写 `_costWarning`
- 填进去的是 models.dev 的估价，不是服务商账单。OpenRouter、kilo、newapi、Copilot、OpenCode Go 等聚合或跨厂商订阅不会被自动处理；要估价就自己写一条映射

## 卸载与禁用

从 `opencode.json` / `opencode.jsonc` 的 `plugins` 数组移除包名或本地路径条目，重启 OpenCode 即卸载。临时禁用填充可移走所选配置文件，或移除其中所有有效的 `mapping` / `costMapping`（插件在没有可用映射时不启用填充；仍会监听文件变化）。映射配置可能位于项目根目录 `oc-auto-model-config.jsonc` / `.json` 或全局 `~/.config/opencode/oc-auto-model-config.jsonc` / `.json`（遵循 `XDG_CONFIG_HOME`），不会自动删除。

models.dev 缓存默认是 `~/.config/opencode/models-dev.json`（设置 `XDG_CONFIG_HOME` 时为 `$XDG_CONFIG_HOME/opencode/models-dev.json`）；启用调试后 dump 默认是同目录的 `expanded-config.json`。卸载不要求清理缓存或 dump；若不再需要这些数据可手动删除对应文件。指定过 `cachePath` / `debug.dumpPath` 时，应检查自己指定的实际路径。
